import { useEffect, useMemo, useState } from 'react'
import { BrowserRouter, NavLink, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import * as Icons from 'lucide-react'
import { format, isValid, parseISO, startOfMonth, subMonths } from 'date-fns'
import { Bar, BarChart, CartesianGrid, Cell, Legend, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import toast from 'react-hot-toast'
import { useExpense } from './context/ExpenseContext'
import { exportBackupJson, exportTransactionsCsv } from './services/exportService'
import { budgetProgress, categoryTotals, monthTotals, periodMetrics, previousPeriod, spendingTrend, totalExpenses, totalIncome } from './utils/calculations'

const iconNames = ['Utensils', 'Car', 'ShoppingBag', 'ReceiptIndianRupee', 'Sparkles', 'HeartPulse', 'GraduationCap', 'Plane', 'House', 'Sparkle', 'MoreHorizontal', 'BriefcaseBusiness', 'Laptop', 'Building2', 'ChartNoAxesCombined', 'Gift', 'CircleDollarSign', 'Coffee', 'WalletCards', 'BadgeIndianRupee', 'ShieldCheck', 'RefreshCw', 'Tag', 'Landmark']
const paymentMethods = ['UPI', 'Card', 'Cash', 'Bank transfer', 'Wallet', 'Direct debit']
const chartColors = ['#5146e5', '#f97316', '#0ea5e9', '#10b981', '#ec4899', '#eab308', '#8b5cf6', '#14b8a6']

const currencySymbols = { INR: '₹', USD: '$', EUR: '€', GBP: '£' }
const money = (value, currency = 'INR', compact = false) => {
  const amount = Number(value || 0)
  return new Intl.NumberFormat('en-IN', { style: 'currency', currency, maximumFractionDigits: 0, notation: compact && Math.abs(amount) >= 100000 ? 'compact' : 'standard' }).format(amount)
}
const shortMoney = (value, currency = 'INR') => money(value, currency, true)
const today = () => format(new Date(), 'yyyy-MM-dd')
const Icon = ({ name, size = 18, strokeWidth = 2, ...props }) => {
  const Component = Icons[name] || Icons.CircleDollarSign
  return <Component size={size} strokeWidth={strokeWidth} {...props} />
}
const categoryFor = (categories, id) => categories.find(category => category.id === id) || { name: 'Uncategorized', color: '#94a3b8', icon: 'CircleDollarSign' }
const dateLabel = (date, pattern = 'dd MMM yyyy') => { try { return format(parseISO(date), pattern) } catch { return date } }

function App() {
  return <BrowserRouter><AppShell /></BrowserRouter>
}

function AppShell() {
  const { preferences, setPreference } = useExpense()
  const location = useLocation()
  const [drawerOpen, setDrawerOpen] = useState(false)
  useEffect(() => { document.documentElement.dataset.theme = preferences.theme }, [preferences.theme])
  useEffect(() => { setDrawerOpen(false) }, [location.pathname, location.search])

  const nav = [
    { to: '/', label: 'Dashboard', icon: 'LayoutDashboard', end: true },
    { to: '/transactions', label: 'Transactions', icon: 'ArrowLeftRight' },
    { to: '/add-transaction', label: 'Add transaction', icon: 'PlusCircle' },
    { to: '/analytics', label: 'Analytics', icon: 'ChartNoAxesCombined' },
    { to: '/budgets', label: 'Budgets', icon: 'Target' },
    { to: '/categories', label: 'Categories', icon: 'Tags' },
    { to: '/settings', label: 'Settings', icon: 'Settings2' }
  ]
  const title = nav.find(item => item.end ? location.pathname === item.to : location.pathname.startsWith(item.to))?.label || 'SpendWise'
  const currentDate = format(new Date(), 'EEEE, dd MMMM yyyy')

  return <div className="app-shell">
    <aside className={`sidebar ${drawerOpen ? 'open' : ''}`}>
      <div className="brand"><div className="brand-mark"><span /></div><span>Spend<span>Wise</span></span></div>
      <div className="workspace-label">PERSONAL FINANCE</div>
      <nav className="nav-list" aria-label="Primary navigation">
        {nav.map(item => <NavLink key={item.to} to={item.to} end={item.end} className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}><Icon name={item.icon} size={18} /><span>{item.label}</span>{item.label === 'Add transaction' && <span className="nav-add">+</span>}</NavLink>)}
      </nav>
      <div className="sidebar-bottom">
        <div className="rail-tip"><Icon name="Sparkles" size={16} /><div><strong>Stay in focus</strong><span>Small habits, clearer money.</span></div></div>
        <button className="user-chip" onClick={() => window.location.assign('/settings')}><span className="avatar">SW</span><span><strong>My workspace</strong><small>Personal account</small></span><Icon name="ChevronRight" size={15} /></button>
      </div>
    </aside>
    {drawerOpen && <button className="drawer-scrim" aria-label="Close navigation" onClick={() => setDrawerOpen(false)} />}
    <div className="main-wrap">
      <header className="topbar">
        <button className="icon-button mobile-menu" onClick={() => setDrawerOpen(true)} aria-label="Open navigation"><Icon name="Menu" /></button>
        <div className="topbar-title"><span className="eyebrow">{currentDate}</span><h1>{title}</h1></div>
        <div className="topbar-actions"><button className="icon-button" onClick={() => setPreference('theme', preferences.theme === 'dark' ? 'light' : 'dark')} aria-label="Toggle theme" title="Toggle theme"><Icon name={preferences.theme === 'dark' ? 'SunMedium' : 'Moon'} /></button><button className="profile-button" onClick={() => window.location.assign('/settings')} aria-label="Open settings"><span className="avatar small">SW</span><Icon name="ChevronDown" size={15} /></button></div>
      </header>
      <main className="content"><Routes>
        <Route path="/" element={<Dashboard />} />
        <Route path="/transactions" element={<TransactionsPage />} />
        <Route path="/transactions/edit/:id" element={<EditTransactionPage />} />
        <Route path="/add-transaction" element={<AddTransactionPage />} />
        <Route path="/analytics" element={<AnalyticsPage />} />
        <Route path="/budgets" element={<BudgetsPage />} />
        <Route path="/categories" element={<CategoriesPage />} />
        <Route path="/settings" element={<SettingsPage />} />
        <Route path="*" element={<NotFound />} />
      </Routes></main>
    </div>
  </div>
}

function PageHeader({ title, description, action }) { return <div className="page-header"><div><span className="eyebrow accent">SPENDWISE / {title.toUpperCase()}</span><h2>{title}</h2><p>{description}</p></div>{action && <div className="header-action">{action}</div>}</div> }
function Button({ children, variant = 'primary', icon, className = '', ...props }) { return <button className={`button button-${variant} ${className}`} {...props}>{icon && <Icon name={icon} size={16} />}{children}</button> }
function IconButton({ label, icon, variant = '', ...props }) { return <button aria-label={label} title={label} className={`icon-button ${variant}`} {...props}><Icon name={icon} size={17} /></button> }
function EmptyState({ icon = 'Inbox', title, description, action }) { return <div className="empty-state"><div className="empty-icon"><Icon name={icon} size={24} /></div><h3>{title}</h3><p>{description}</p>{action}</div> }
function Modal({ open, title, description, onClose, children, width = '520px' }) {
  useEffect(() => { if (!open) return; const handler = event => event.key === 'Escape' && onClose(); document.addEventListener('keydown', handler); return () => document.removeEventListener('keydown', handler) }, [open, onClose])
  if (!open) return null
  return <div className="modal-backdrop" role="presentation" onMouseDown={event => event.target === event.currentTarget && onClose()}><div className="modal" style={{ maxWidth: width }} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-head"><div><h3 id="modal-title">{title}</h3>{description && <p>{description}</p>}</div><IconButton label="Close dialog" icon="X" onClick={onClose} /></div>{children}</div></div>
}
function StatCard({ label, value, icon, tone = 'indigo', note, trend }) { return <article className={`stat-card ${tone}`}><div className="stat-top"><span>{label}</span><span className="stat-icon"><Icon name={icon} size={18} /></span></div><strong className="stat-value">{value}</strong><div className={`stat-note ${trend === 'up' ? 'positive' : trend === 'down' ? 'negative' : ''}`}>{trend && <Icon name={trend === 'up' ? 'ArrowUpRight' : 'ArrowDownRight'} size={14} />}{note}</div></article> }
function SectionCard({ title, subtitle, action, children, className = '' }) { return <section className={`section-card ${className}`}><div className="section-head"><div><h3>{title}</h3>{subtitle && <p>{subtitle}</p>}</div>{action}</div>{children}</section> }
function ProgressBar({ value, state = 'normal' }) { return <div className="progress-track"><div className={`progress-fill ${state}`} style={{ width: `${Math.min(value, 100)}%` }} /></div> }
function CategoryPill({ category }) { return <span className="category-pill"><i style={{ backgroundColor: category.color }} />{category.name}</span> }

function Dashboard() {
  const { transactions, budgets, categories, preferences } = useExpense()
  const navigate = useNavigate()
  const currentMonth = format(new Date(), 'yyyy-MM')
  const monthSet = transactions.filter(item => item.date.startsWith(currentMonth))
  const income = totalIncome(transactions)
  const expenses = totalExpenses(transactions)
  const currentExpenses = totalExpenses(monthSet)
  const currentIncome = totalIncome(monthSet)
  const currentBudgets = budgets.filter(budget => budget.month === currentMonth)
  const budgetLimit = currentBudgets.filter(budget => budget.categoryId === 'total').reduce((sum, budget) => sum + budget.amount, 0)
  const currentBudgetRemaining = budgetLimit ? budgetLimit - currentExpenses : null
  const savings = income ? ((income - expenses) / income) * 100 : null
  const months = monthTotals(transactions, preferences.dashboardRange || 6)
  const pieData = categoryTotals(monthSet.length ? monthSet : transactions, categories)
  const recent = [...transactions].sort((a, b) => new Date(b.date) - new Date(a.date) || new Date(b.createdAt) - new Date(a.createdAt)).slice(0, 5)
  const currentMonthBudgets = currentBudgets.filter(item => item.categoryId !== 'total')
  const previousKey = format(subMonths(new Date(), 1), 'yyyy-MM')
  const previousSet = transactions.filter(item => item.date.startsWith(previousKey))
  const expenseChange = previousSet.length ? ((currentExpenses - totalExpenses(previousSet)) / Math.max(totalExpenses(previousSet), 1)) * 100 : null
  const incomeChange = previousSet.length ? ((currentIncome - totalIncome(previousSet)) / Math.max(totalIncome(previousSet), 1)) * 100 : null
  const [trendMode, setTrendMode] = useState('monthly')
  const trend = spendingTrend(transactions, trendMode)
  return <>
    <PageHeader title="Dashboard" description="Your money, in focus." action={<Button icon="Plus" onClick={() => navigate('/add-transaction')}>Add transaction</Button>} />
    {preferences.demoData && <div className="demo-banner"><span className="demo-dot" /><div><strong>You’re viewing sample data</strong><span>Explore SpendWise with realistic transactions. Add your own to make it yours.</span></div><button onClick={() => navigate('/settings')}>Manage sample data <Icon name="ArrowUpRight" size={14} /></button></div>}
    <div className="stats-grid">
      <StatCard label="Total balance" value={money(income - expenses, preferences.currency)} icon="WalletCards" tone="indigo" note="Across all recorded activity" />
      <StatCard label="Total income" value={money(income, preferences.currency)} icon="ArrowDownToLine" tone="green" note={incomeChange === null ? 'No comparison data' : `${Math.abs(incomeChange).toFixed(1)}% vs last month`} trend={incomeChange === null ? null : incomeChange >= 0 ? 'up' : 'down'} />
      <StatCard label="Total expenses" value={money(expenses, preferences.currency)} icon="ArrowUpFromLine" tone="coral" note={expenseChange === null ? 'No comparison data' : `${Math.abs(expenseChange).toFixed(1)}% vs last month`} trend={expenseChange === null ? null : expenseChange <= 0 ? 'up' : 'down'} />
      <StatCard label="Monthly budget" value={currentBudgetRemaining === null ? 'Not set' : money(currentBudgetRemaining, preferences.currency)} icon="Target" tone="amber" note={currentBudgetRemaining === null ? 'Set a limit in Budgets' : `${money(currentExpenses, preferences.currency)} used this month`} />
      <StatCard label="Savings rate" value={savings === null ? '—' : `${savings.toFixed(1)}%`} icon="Sparkles" tone="violet" note={savings === null ? 'Add income to calculate' : 'Based on all recorded income'} />
    </div>
    <div className="dashboard-grid">
      <SectionCard title="Income vs expenses" subtitle="Actual activity by month" className="span-2" action={<span className="chart-legend"><i className="legend-income" /> Income <i className="legend-expense" /> Expenses</span>}>
        <div className="chart-box bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={months} barGap={8}><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 3" /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickFormatter={v => shortMoney(v, preferences.currency)} width={58} /><Tooltip formatter={(value, name) => [money(value, preferences.currency), name === 'income' ? 'Income' : 'Expenses']} contentStyle={{ background: 'var(--surface-elevated)', border: '1px solid var(--border)', borderRadius: 12 }} /><Bar dataKey="income" fill="#16a34a" radius={[5, 5, 0, 0]} /><Bar dataKey="expenses" fill="#f26b5e" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></div>
      </SectionCard>
      <SectionCard title="Expense breakdown" subtitle={pieData.length ? 'Where your money is going' : 'No expenses to show'} className="pie-panel">
        {pieData.length ? <><div className="chart-box pie-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={pieData} dataKey="total" nameKey="name" innerRadius="62%" outerRadius="84%" paddingAngle={3} onClick={item => navigate(`/transactions?category=${item.id}`)}>{pieData.map((item, index) => <Cell key={item.id} fill={item.color || chartColors[index % chartColors.length]} />)}</Pie><Tooltip formatter={value => money(value, preferences.currency)} contentStyle={{ background: 'var(--surface-elevated)', border: '1px solid var(--border)', borderRadius: 12 }} /></PieChart></ResponsiveContainer></div><div className="pie-legend">{pieData.slice(0, 5).map(item => <button key={item.id} onClick={() => navigate(`/transactions?category=${item.id}`)}><span><i style={{ background: item.color }} />{item.name}</span><strong>{money(item.total, preferences.currency)}</strong></button>)}</div></> : <EmptyState icon="PieChart" title="No expenses yet" description="Add an expense to see the breakdown." action={<Button variant="secondary" onClick={() => navigate('/add-transaction')}>Add expense</Button>} />}
      </SectionCard>
      <SectionCard title="Spending trend" subtitle="Expense movement over time" className="span-2" action={<div className="segmented small"><button className={trendMode === 'weekly' ? 'active' : ''} onClick={() => setTrendMode('weekly')}>Weekly</button><button className={trendMode === 'monthly' ? 'active' : ''} onClick={() => setTrendMode('monthly')}>Monthly</button><button className={trendMode === 'yearly' ? 'active' : ''} onClick={() => setTrendMode('yearly')}>Yearly</button></div>}>
        <div className="chart-box line-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={trend}><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 3" /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickFormatter={v => shortMoney(v, preferences.currency)} width={58} /><Tooltip formatter={value => [money(value, preferences.currency), 'Expenses']} contentStyle={{ background: 'var(--surface-elevated)', border: '1px solid var(--border)', borderRadius: 12 }} /><Line type="monotone" dataKey="amount" stroke="#5146e5" strokeWidth={3} dot={{ r: 3, fill: '#5146e5', strokeWidth: 2, stroke: 'var(--surface)' }} activeDot={{ r: 6 }} /></LineChart></ResponsiveContainer></div>
      </SectionCard>
      <SectionCard title="Budget overview" subtitle={`For ${format(new Date(), 'MMMM yyyy')}`} action={<NavLink className="text-link" to="/budgets">View budgets <Icon name="ArrowUpRight" size={14} /></NavLink>}>
        {currentMonthBudgets.length ? <div className="budget-list">{currentMonthBudgets.slice(0, 4).map(budget => <BudgetMini key={budget.id} budget={budget} categories={categories} transactions={transactions} currency={preferences.currency} />)}</div> : <EmptyState icon="Target" title="No monthly budgets" description="Set a limit to make your spending plan visible." action={<NavLink className="text-link" to="/budgets">Create a budget <Icon name="ArrowRight" size={14} /></NavLink>} />}
      </SectionCard>
      <SectionCard title="Recent transactions" subtitle="Your latest activity" action={<NavLink className="text-link" to="/transactions">View all <Icon name="ArrowUpRight" size={14} /></NavLink>} className="span-2">
        {recent.length ? <div className="transaction-list">{recent.map(item => <TransactionRow key={item.id} item={item} category={categoryFor(categories, item.categoryId)} currency={preferences.currency} compact />)}</div> : <EmptyState icon="ArrowLeftRight" title="No transactions yet" description="Your newest activity will show up here." action={<Button onClick={() => navigate('/add-transaction')}>Add transaction</Button>} />}
      </SectionCard>
    </div>
  </>
}

function BudgetMini({ budget, categories, transactions, currency }) { const progress = budgetProgress(budget, transactions); const category = budget.categoryId === 'total' ? { name: 'Total spending', color: '#5146e5' } : categoryFor(categories, budget.categoryId); return <div className="budget-mini"><div className="budget-mini-top"><span><i style={{ background: category.color }} />{category.name}</span><strong>{money(progress.spent, currency)} <small>/ {money(budget.amount, currency)}</small></strong></div><ProgressBar value={progress.percentage} state={progress.state} /><div className="budget-mini-bottom"><span>{progress.percentage.toFixed(0)}% used</span><span className={progress.state}>{progress.remaining >= 0 ? `${money(progress.remaining, currency)} left` : `${money(Math.abs(progress.remaining), currency)} over`}</span></div></div> }
function TransactionRow({ item, category, currency, compact = false, onView }) { return <div className={`transaction-row ${compact ? 'compact' : ''}`}><div className="transaction-main"><span className="transaction-icon" style={{ background: `${category.color}18`, color: category.color }}><Icon name={category.icon} size={17} /></span><div><strong>{item.description}</strong><span>{category.name} · {dateLabel(item.date)}</span></div></div><span className="payment-method">{item.paymentMethod}</span><strong className={`transaction-amount ${item.type}`}>{item.type === 'income' ? '+' : '−'}{money(item.amount, currency)}</strong>{onView && <IconButton label="View transaction" icon="Eye" onClick={() => onView(item)} />}</div> }

function TransactionsPage() {
  const { transactions, categories, preferences, deleteTransaction } = useExpense()
  const navigate = useNavigate()
  const [searchParams, setSearchParams] = useSearchParams()
  const [filters, setFilters] = useState(() => ({ search: '', type: '', category: searchParams.get('category') || '', payment: '', startDate: '', endDate: '', minAmount: '', maxAmount: '' }))
  const [sort, setSort] = useState('date')
  const [direction, setDirection] = useState('desc')
  const [pageSize, setPageSize] = useState(8)
  const [page, setPage] = useState(1)
  const [viewing, setViewing] = useState(null)
  const [deleting, setDeleting] = useState(null)
  useEffect(() => { setPage(1) }, [JSON.stringify(filters), sort, direction, pageSize])
  const filtered = useMemo(() => {
    const value = transactions.filter(item => {
      const text = `${item.description} ${item.notes || ''}`.toLowerCase()
      return (!filters.search || text.includes(filters.search.toLowerCase())) && (!filters.type || item.type === filters.type) && (!filters.category || item.categoryId === filters.category) && (!filters.payment || item.paymentMethod === filters.payment) && (!filters.startDate || item.date >= filters.startDate) && (!filters.endDate || item.date <= filters.endDate) && (!filters.minAmount || item.amount >= Number(filters.minAmount)) && (!filters.maxAmount || item.amount <= Number(filters.maxAmount))
    })
    return value.sort((a, b) => { const av = sort === 'description' ? a.description.toLowerCase() : sort === 'category' ? categoryFor(categories, a.categoryId).name.toLowerCase() : sort === 'amount' ? a.amount : a.date; const bv = sort === 'description' ? b.description.toLowerCase() : sort === 'category' ? categoryFor(categories, b.categoryId).name.toLowerCase() : sort === 'amount' ? b.amount : b.date; const result = av > bv ? 1 : av < bv ? -1 : 0; return direction === 'asc' ? result : -result })
  }, [transactions, categories, filters, sort, direction])
  const pages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const rows = filtered.slice((page - 1) * pageSize, page * pageSize)
  const updateFilter = (key, value) => setFilters(previous => ({ ...previous, [key]: value }))
  const reset = () => { setFilters({ search: '', type: '', category: '', payment: '', startDate: '', endDate: '', minAmount: '', maxAmount: '' }); setSearchParams({}) }
  const confirmDelete = () => { deleteTransaction(deleting.id); toast.success('Transaction deleted'); setDeleting(null) }
  return <>
    <PageHeader title="Transactions" description="Search, understand, and shape your financial history." action={<Button icon="Plus" onClick={() => navigate('/add-transaction')}>Add transaction</Button>} />
    <SectionCard title="All activity" subtitle={`${filtered.length} transaction${filtered.length === 1 ? '' : 's'} match your view`}>
      <div className="filter-toolbar"><label className="search-field"><Icon name="Search" size={17} /><input value={filters.search} onChange={event => updateFilter('search', event.target.value)} placeholder="Search description or notes" /></label><select value={filters.type} onChange={event => updateFilter('type', event.target.value)}><option value="">All types</option><option value="income">Income</option><option value="expense">Expense</option></select><select value={filters.category} onChange={event => updateFilter('category', event.target.value)}><option value="">All categories</option>{categories.map(category => <option value={category.id} key={category.id}>{category.name}</option>)}</select><select value={filters.payment} onChange={event => updateFilter('payment', event.target.value)}><option value="">All payment methods</option>{paymentMethods.map(method => <option key={method}>{method}</option>)}</select><Button variant="ghost" icon="SlidersHorizontal" onClick={() => document.getElementById('advanced-filters').classList.toggle('visible')}>More filters</Button></div>
      <div id="advanced-filters" className="advanced-filters"><label>From<input type="date" value={filters.startDate} onChange={event => updateFilter('startDate', event.target.value)} /></label><label>To<input type="date" value={filters.endDate} onChange={event => updateFilter('endDate', event.target.value)} /></label><label>Min amount<input type="number" min="0" value={filters.minAmount} onChange={event => updateFilter('minAmount', event.target.value)} placeholder="0" /></label><label>Max amount<input type="number" min="0" value={filters.maxAmount} onChange={event => updateFilter('maxAmount', event.target.value)} placeholder="Any" /></label><Button variant="ghost" icon="RotateCcw" onClick={reset}>Reset filters</Button></div>
      <div className="table-tools"><div className="table-count">Showing {rows.length ? (page - 1) * pageSize + 1 : 0}–{Math.min(page * pageSize, filtered.length)} of {filtered.length}</div><div className="table-sort"><span>Sort by</span><select value={sort} onChange={event => setSort(event.target.value)}><option value="date">Date</option><option value="amount">Amount</option><option value="description">Description</option><option value="category">Category</option></select><IconButton label="Toggle sort direction" icon={direction === 'asc' ? 'ArrowUpAZ' : 'ArrowDownAZ'} onClick={() => setDirection(value => value === 'asc' ? 'desc' : 'asc')} /><select value={pageSize} onChange={event => setPageSize(Number(event.target.value))}><option value="8">8 / page</option><option value="15">15 / page</option><option value="30">30 / page</option></select><Button variant="secondary" icon="Download" onClick={() => { exportTransactionsCsv(filtered, categories, preferences.currency); toast.success('CSV export ready') }}>Export CSV</Button></div></div>
      {rows.length ? <><div className="transaction-table"><div className="table-header"><span>Description</span><span>Category</span><span>Date</span><span>Method</span><span>Amount</span><span>Actions</span></div>{rows.map(item => <TransactionTableRow key={item.id} item={item} category={categoryFor(categories, item.categoryId)} currency={preferences.currency} onView={setViewing} onDelete={setDeleting} onEdit={() => navigate(`/transactions/edit/${item.id}`)} />)}</div><div className="mobile-transaction-list">{rows.map(item => <MobileTransactionCard key={item.id} item={item} category={categoryFor(categories, item.categoryId)} currency={preferences.currency} onView={setViewing} onDelete={setDeleting} onEdit={() => navigate(`/transactions/edit/${item.id}`)} />)}</div></> : <EmptyState icon="SearchX" title="No transactions found" description="Try adjusting your filters or add a new transaction." action={<Button variant="secondary" onClick={reset}>Clear filters</Button>} />}
      {filtered.length > pageSize && <div className="pagination"><Button variant="ghost" icon="ChevronLeft" disabled={page === 1} onClick={() => setPage(value => value - 1)}>Previous</Button><span>Page {page} of {pages}</span><Button variant="ghost" disabled={page === pages} onClick={() => setPage(value => value + 1)}>Next <Icon name="ChevronRight" size={15} /></Button></div>}
    </SectionCard>
    <TransactionDetail item={viewing} category={viewing ? categoryFor(categories, viewing.categoryId) : null} currency={preferences.currency} onClose={() => setViewing(null)} />
    <Modal open={Boolean(deleting)} title="Delete transaction?" description="This action cannot be undone." onClose={() => setDeleting(null)}><div className="confirm-body"><div className="confirm-icon danger"><Icon name="Trash2" /></div><p>Delete <strong>{deleting?.description}</strong> and remove it from all totals, charts, and budgets?</p></div><div className="modal-actions"><Button variant="ghost" onClick={() => setDeleting(null)}>Cancel</Button><Button variant="danger" onClick={confirmDelete} icon="Trash2">Delete transaction</Button></div></Modal>
  </>
}
function TransactionTableRow({ item, category, currency, onView, onDelete, onEdit }) { return <div className="table-row"><div className="table-description"><span className="transaction-icon" style={{ background: `${category.color}18`, color: category.color }}><Icon name={category.icon} size={16} /></span><strong>{item.description}</strong></div><CategoryPill category={category} /><span>{dateLabel(item.date)}</span><span className="muted-text">{item.paymentMethod}</span><strong className={`transaction-amount ${item.type}`}>{item.type === 'income' ? '+' : '−'}{money(item.amount, currency)}</strong><div className="row-actions"><IconButton label="View transaction" icon="Eye" onClick={() => onView(item)} /><IconButton label="Edit transaction" icon="Pencil" onClick={onEdit} /><IconButton label="Delete transaction" icon="Trash2" variant="danger-icon" onClick={() => onDelete(item)} /></div></div> }
function MobileTransactionCard({ item, category, currency, onView, onDelete, onEdit }) { return <div className="mobile-txn-card"><div className="mobile-txn-top"><div className="table-description"><span className="transaction-icon" style={{ background: `${category.color}18`, color: category.color }}><Icon name={category.icon} size={16} /></span><strong>{item.description}</strong></div><strong className={`transaction-amount ${item.type}`}>{item.type === 'income' ? '+' : '−'}{money(item.amount, currency)}</strong></div><div className="mobile-txn-meta"><CategoryPill category={category} /><span>{dateLabel(item.date)}</span><span>{item.paymentMethod}</span></div><div className="row-actions"><Button variant="ghost" icon="Eye" onClick={() => onView(item)}>View</Button><Button variant="ghost" icon="Pencil" onClick={onEdit}>Edit</Button><IconButton label="Delete transaction" icon="Trash2" variant="danger-icon" onClick={() => onDelete(item)} /></div></div> }
function TransactionDetail({ item, category, currency, onClose }) { return <Modal open={Boolean(item)} title="Transaction details" onClose={onClose}><div className="detail-hero"><span className="transaction-icon large" style={{ background: `${category?.color}18`, color: category?.color }}><Icon name={category?.icon} size={24} /></span><div><span className="eyebrow">{item?.type === 'income' ? 'INCOME' : 'EXPENSE'}</span><h4>{item?.description}</h4><strong className={`detail-amount ${item?.type}`}>{item?.type === 'income' ? '+' : '−'}{money(item?.amount, currency)}</strong></div></div><div className="detail-grid"><div><span>Date</span><strong>{item && dateLabel(item.date)}</strong></div><div><span>Category</span><strong>{category?.name}</strong></div><div><span>Payment method</span><strong>{item?.paymentMethod}</strong></div><div><span>Notes</span><strong>{item?.notes || 'No notes added'}</strong></div></div></Modal> }

function TransactionForm({ initial, onSubmit, onCancel, submitLabel = 'Save transaction' }) {
  const { categories } = useExpense()
  const [form, setForm] = useState(() => initial || { type: 'expense', amount: '', description: '', categoryId: categories.find(item => item.type === 'expense')?.id || '', date: today(), paymentMethod: 'UPI', notes: '' })
  const [errors, setErrors] = useState({})
  const [saving, setSaving] = useState(false)
  const filteredCategories = categories.filter(item => item.type === form.type)
  useEffect(() => { if (!filteredCategories.some(item => item.id === form.categoryId)) setForm(previous => ({ ...previous, categoryId: filteredCategories[0]?.id || '' })) }, [form.type])
  const set = (key, value) => setForm(previous => ({ ...previous, [key]: value }))
  const submit = async event => {
    event.preventDefault()
    const nextErrors = {}
    if (!form.description.trim()) nextErrors.description = 'Description is required.'
    if (!form.amount || Number(form.amount) <= 0) nextErrors.amount = 'Amount must be greater than zero.'
    if (!form.categoryId) nextErrors.categoryId = 'Choose a category.'
    if (!form.date || !isValid(parseISO(form.date))) nextErrors.date = 'Choose a valid date.'
    if (!form.paymentMethod) nextErrors.paymentMethod = 'Choose a payment method.'
    setErrors(nextErrors)
    if (Object.keys(nextErrors).length) return
    setSaving(true)
    await onSubmit({ ...form, amount: Number(form.amount) })
    setSaving(false)
  }
  return <form className="form-card" onSubmit={submit} noValidate><div className="type-toggle"><button type="button" className={form.type === 'expense' ? 'active expense' : ''} onClick={() => set('type', 'expense')}><Icon name="ArrowUpFromLine" size={17} />Expense</button><button type="button" className={form.type === 'income' ? 'active income' : ''} onClick={() => set('type', 'income')}><Icon name="ArrowDownToLine" size={17} />Income</button></div><div className="form-grid"><label className="field full"><span>Amount <em>*</em></span><div className="amount-input"><span>{currencySymbols.INR}</span><input autoFocus type="number" min="0.01" step="0.01" value={form.amount} onChange={event => set('amount', event.target.value)} placeholder="0.00" /></div>{errors.amount && <small className="field-error">{errors.amount}</small>}</label><label className="field full"><span>Description <em>*</em></span><input value={form.description} onChange={event => set('description', event.target.value)} placeholder="e.g. Monthly groceries" />{errors.description && <small className="field-error">{errors.description}</small>}</label><label className="field"><span>Category <em>*</em></span><select value={form.categoryId} onChange={event => set('categoryId', event.target.value)}>{filteredCategories.map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select>{errors.categoryId && <small className="field-error">{errors.categoryId}</small>}</label><label className="field"><span>Date <em>*</em></span><input type="date" value={form.date} onChange={event => set('date', event.target.value)} />{errors.date && <small className="field-error">{errors.date}</small>}</label><label className="field"><span>Payment method <em>*</em></span><select value={form.paymentMethod} onChange={event => set('paymentMethod', event.target.value)}>{paymentMethods.map(method => <option key={method}>{method}</option>)}</select>{errors.paymentMethod && <small className="field-error">{errors.paymentMethod}</small>}</label><label className="field full"><span>Notes <small>(optional)</small></span><textarea rows="4" value={form.notes} onChange={event => set('notes', event.target.value)} placeholder="Add context to remember later" /></label></div><div className="form-actions"><Button type="button" variant="ghost" onClick={onCancel}>Cancel</Button><Button type="submit" disabled={saving} icon={saving ? 'LoaderCircle' : 'Check'}>{saving ? 'Saving…' : submitLabel}</Button></div></form>
}
function AddTransactionPage() { const { addTransaction } = useExpense(); const navigate = useNavigate(); const submit = async data => { addTransaction(data); toast.success('Transaction added'); navigate('/transactions') }; return <><PageHeader title="Add transaction" description="Capture the moment while it is still fresh." /><div className="narrow-content"><TransactionForm onSubmit={submit} onCancel={() => navigate(-1)} /></div></> }
function EditTransactionPage() { const { id } = useParams(); const { transactions, updateTransaction } = useExpense(); const navigate = useNavigate(); const item = transactions.find(transaction => transaction.id === id); if (!item) return <EmptyState icon="SearchX" title="Transaction not found" description="This transaction may have been removed." action={<Button onClick={() => navigate('/transactions')}>Back to transactions</Button>} />; const submit = async data => { updateTransaction(id, data); toast.success('Transaction updated'); navigate('/transactions') }; return <><PageHeader title="Edit transaction" description="Keep your record accurate and up to date." /><div className="narrow-content"><TransactionForm initial={item} onSubmit={submit} onCancel={() => navigate(-1)} submitLabel="Save changes" /></div></> }

function AnalyticsPage() {
  const { transactions, categories, preferences } = useExpense()
  const defaultStart = format(subMonths(new Date(), 5), 'yyyy-MM-dd')
  const [startDate, setStartDate] = useState(defaultStart)
  const [endDate, setEndDate] = useState(today())
  const [categoryFilter, setCategoryFilter] = useState('')
  const [granularity, setGranularity] = useState('monthly')
  const start = parseISO(startDate); const end = parseISO(endDate)
  const filteredTransactions = transactions.filter(item => (!categoryFilter || item.categoryId === categoryFilter))
  const metrics = periodMetrics(filteredTransactions, start, end)
  const previous = previousPeriod(start, end)
  const priorMetrics = periodMetrics(filteredTransactions, previous.start, previous.end)
  const hasPrior = priorMetrics.items.length > 0
  const categoriesData = categoryTotals(metrics.items, categories).slice(0, 8)
  const trend = spendingTrend(filteredTransactions, granularity, end, start)
  const setRange = days => { const next = new Date(); next.setDate(next.getDate() - days); setStartDate(format(next, 'yyyy-MM-dd')); setEndDate(today()) }
  return <><PageHeader title="Analytics" description="The patterns behind your everyday money." action={<div className="date-range-actions"><button onClick={() => setRange(30)}>30 days</button><button onClick={() => setRange(90)}>90 days</button><button onClick={() => setRange(180)}>6 months</button></div>} /><SectionCard title="Analysis controls" className="analytics-controls"><label className="field"><span>From</span><input type="date" value={startDate} onChange={event => setStartDate(event.target.value)} /></label><label className="field"><span>To</span><input type="date" value={endDate} onChange={event => setEndDate(event.target.value)} /></label><label className="field"><span>Category</span><select value={categoryFilter} onChange={event => setCategoryFilter(event.target.value)}><option value="">All expense categories</option>{categories.filter(category => category.type === 'expense').map(category => <option value={category.id} key={category.id}>{category.name}</option>)}</select></label><label className="field"><span>Spending view</span><select value={granularity} onChange={event => setGranularity(event.target.value)}><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option><option value="yearly">Yearly</option></select></label></SectionCard><div className="stats-grid four"><StatCard label="Income" value={money(metrics.income, preferences.currency)} icon="ArrowDownToLine" tone="green" note={hasPrior ? `${money(Math.abs(metrics.income - priorMetrics.income), preferences.currency)} vs prior period` : 'No comparison data'} /><StatCard label="Expenses" value={money(metrics.expenses, preferences.currency)} icon="ArrowUpFromLine" tone="coral" note={hasPrior ? `${money(Math.abs(metrics.expenses - priorMetrics.expenses), preferences.currency)} vs prior period` : 'No comparison data'} /><StatCard label="Net cash flow" value={money(metrics.net, preferences.currency)} icon="Activity" tone="indigo" note={metrics.net >= 0 ? 'Positive cash flow' : 'More out than in'} /><StatCard label="Savings rate" value={metrics.rate === null ? '—' : `${metrics.rate.toFixed(1)}%`} icon="Sparkles" tone="violet" note={metrics.items.length ? `${metrics.items.length} transactions analyzed` : 'No data in this range'} /></div>{metrics.items.length ? <div className="dashboard-grid analytics-grid"><SectionCard title="Spending trend" subtitle="Expense totals for the selected period" className="span-2"><div className="chart-box analytics-line"><ResponsiveContainer width="100%" height="100%"><LineChart data={trend}><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 3" /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickFormatter={v => shortMoney(v, preferences.currency)} width={54} /><Tooltip formatter={value => [money(value, preferences.currency), 'Expenses']} contentStyle={{ background: 'var(--surface-elevated)', border: '1px solid var(--border)', borderRadius: 12 }} /><Line type="monotone" dataKey="amount" stroke="#5146e5" strokeWidth={3} dot={false} /></LineChart></ResponsiveContainer></div></SectionCard><SectionCard title="Category distribution" subtitle="Highest spend categories"><div className="chart-box analytics-pie"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoriesData} dataKey="total" nameKey="name" innerRadius="58%" outerRadius="82%" paddingAngle={4}>{categoriesData.map((item, index) => <Cell key={item.id} fill={item.color || chartColors[index % chartColors.length]} />)}</Pie><Tooltip formatter={value => money(value, preferences.currency)} contentStyle={{ background: 'var(--surface-elevated)', border: '1px solid var(--border)', borderRadius: 12 }} /></PieChart></ResponsiveContainer></div><div className="rank-list">{categoriesData.slice(0, 5).map((item, index) => <div key={item.id}><span className="rank"><b>{index + 1}</b><i style={{ background: item.color }} />{item.name}</span><strong>{money(item.total, preferences.currency)}</strong></div>)}</div></SectionCard><SectionCard title="Period highlights" subtitle="The numbers worth a closer look"><div className="highlight-list"><div><span>Highest expense</span><strong>{metrics.highestExpense ? money(metrics.highestExpense.amount, preferences.currency) : '—'}</strong><small>{metrics.highestExpense?.description || 'No expenses in this range'}</small></div><div><span>Average transaction</span><strong>{metrics.average ? money(metrics.average, preferences.currency) : '—'}</strong><small>Across income and expenses</small></div><div><span>Top category</span><strong>{categoriesData[0]?.name || '—'}</strong><small>{categoriesData[0] ? money(categoriesData[0].total, preferences.currency) : 'No category data'}</small></div></div></SectionCard></div> : <EmptyState icon="ChartNoAxesCombined" title="No analytics for this range" description="Choose a wider date range or add a transaction to start seeing patterns." />}</>
}

function BudgetsPage() {
  const { budgets, transactions, categories, preferences, addBudget, updateBudget, deleteBudget } = useExpense()
  const [selectedMonth, setSelectedMonth] = useState(format(new Date(), 'yyyy-MM'))
  const [editing, setEditing] = useState(null)
  const [deleting, setDeleting] = useState(null)
  const [form, setForm] = useState({ categoryId: 'total', amount: '', month: format(new Date(), 'yyyy-MM') })
  const monthBudgets = budgets.filter(item => item.month === selectedMonth)
  const set = (key, value) => setForm(previous => ({ ...previous, [key]: value }))
  const submit = event => { event.preventDefault(); if (!form.amount || Number(form.amount) <= 0) return toast.error('Enter a budget amount greater than zero.'); const duplicate = budgets.find(item => item.month === form.month && item.categoryId === form.categoryId && item.id !== editing?.id); if (duplicate) return toast.error('A budget already exists for that category and month. Edit the existing one instead.'); if (editing) { updateBudget(editing.id, form); toast.success('Budget updated') } else { addBudget(form); toast.success('Budget created') } setForm({ categoryId: 'total', amount: '', month: selectedMonth }); setEditing(null) }
  const startEdit = item => { setEditing(item); setForm({ categoryId: item.categoryId, amount: item.amount, month: item.month }) }
  const confirmDelete = () => { deleteBudget(deleting.id); toast.success('Budget deleted'); setDeleting(null) }
  return <><PageHeader title="Budgets" description="Give every rupee a job before the month begins." /><div className="budget-layout"><SectionCard title={editing ? 'Edit budget' : 'Create a budget'} subtitle="Category budgets use expense transactions only"><form className="stack-form" onSubmit={submit}><label className="field"><span>Budget scope</span><select value={form.categoryId} onChange={event => set('categoryId', event.target.value)}><option value="total">Total monthly spending</option>{categories.filter(category => category.type === 'expense').map(category => <option value={category.id} key={category.id}>{category.name}</option>)}</select></label><label className="field"><span>Month</span><input type="month" value={form.month} onChange={event => set('month', event.target.value)} /></label><label className="field"><span>Limit amount</span><div className="amount-input"><span>{currencySymbols[preferences.currency]}</span><input type="number" min="1" step="1" value={form.amount} onChange={event => set('amount', event.target.value)} placeholder="45,000" /></div></label><div className="form-actions"><Button type="button" variant="ghost" onClick={() => { setEditing(null); setForm({ categoryId: 'total', amount: '', month: selectedMonth }) }}>{editing ? 'Cancel edit' : 'Clear'}</Button><Button type="submit" icon="Check">{editing ? 'Save changes' : 'Add budget'}</Button></div></form></SectionCard><SectionCard title="Budget health" subtitle="Track your plan for the selected month" action={<input className="month-picker" type="month" value={selectedMonth} onChange={event => setSelectedMonth(event.target.value)} /> } className="budget-health"><div className="budget-cards">{monthBudgets.length ? monthBudgets.map(item => <BudgetCard key={item.id} budget={item} categories={categories} transactions={transactions} currency={preferences.currency} onEdit={() => startEdit(item)} onDelete={() => setDeleting(item)} />) : <EmptyState icon="Target" title="No budgets for this month" description="Add a total limit or a category plan to get started." />}</div></SectionCard></div><SectionCard title="How budget status works" subtitle="Simple signals, no surprises"><div className="status-guide"><div><span className="status-dot normal" /><strong>Normal</strong><p>Below 75% consumed</p></div><div><span className="status-dot warning" /><strong>Warning</strong><p>75% to below 100%</p></div><div><span className="status-dot exceeded" /><strong>Exceeded</strong><p>100% or more</p></div></div></SectionCard><Modal open={Boolean(deleting)} title="Delete budget?" description="Your transaction history will stay intact." onClose={() => setDeleting(null)}><div className="confirm-body"><div className="confirm-icon danger"><Icon name="Trash2" /></div><p>Delete the {deleting?.categoryId === 'total' ? 'total spending' : categoryFor(categories, deleting?.categoryId).name} budget for {deleting?.month}?</p></div><div className="modal-actions"><Button variant="ghost" onClick={() => setDeleting(null)}>Cancel</Button><Button variant="danger" onClick={confirmDelete} icon="Trash2">Delete budget</Button></div></Modal></>
}
function BudgetCard({ budget, categories, transactions, currency, onEdit, onDelete }) { const progress = budgetProgress(budget, transactions); const category = budget.categoryId === 'total' ? { name: 'Total monthly spending', icon: 'Target', color: '#5146e5' } : categoryFor(categories, budget.categoryId); return <div className={`budget-card ${progress.state}`}><div className="budget-card-head"><div className="budget-title"><span className="category-icon" style={{ background: `${category.color}18`, color: category.color }}><Icon name={category.icon} /></span><div><strong>{category.name}</strong><small>{budget.month}</small></div></div><div className="row-actions"><IconButton label="Edit budget" icon="Pencil" onClick={onEdit} /><IconButton label="Delete budget" icon="Trash2" variant="danger-icon" onClick={onDelete} /></div></div><div className="budget-big-number"><strong>{money(progress.spent, currency)}</strong><span>of {money(budget.amount, currency)}</span></div><ProgressBar value={progress.percentage} state={progress.state} /><div className="budget-card-foot"><span>{progress.percentage.toFixed(0)}% used</span><strong className={progress.state}>{progress.remaining >= 0 ? `${money(progress.remaining, currency)} remaining` : `${money(Math.abs(progress.remaining), currency)} over limit`}</strong></div></div> }

function CategoriesPage() {
  const { categories, transactions, addCategory, updateCategory, deleteCategory } = useExpense()
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState({ name: '', type: 'expense', color: '#5146e5', icon: 'Tag' })
  const [deleting, setDeleting] = useState(null)
  const set = (key, value) => setForm(previous => ({ ...previous, [key]: value }))
  const submit = event => { event.preventDefault(); if (!form.name.trim()) return toast.error('Category name is required.'); if (editing) { updateCategory(editing.id, form); toast.success('Category updated') } else { addCategory(form); toast.success('Category created') } setEditing(null); setForm({ name: '', type: 'expense', color: '#5146e5', icon: 'Tag' }) }
  const startEdit = category => { setEditing(category); setForm({ name: category.name, type: category.type, color: category.color, icon: category.icon }) }
  const requestDelete = category => { if (!category.custom) return toast.error('Default categories are protected.'); if (transactions.some(item => item.categoryId === category.id)) return toast.error('This category is in use. Reassign its transactions before deleting it.'); setDeleting(category) }
  const confirmDelete = () => { deleteCategory(deleting.id); toast.success('Category deleted'); setDeleting(null) }
  return <><PageHeader title="Categories" description="Make your money language feel like your own." /><div className="category-layout"><SectionCard title={editing ? 'Edit category' : 'Create a category'} subtitle="Use colors and icons to make scanning effortless"><form className="stack-form" onSubmit={submit}><label className="field"><span>Name</span><input value={form.name} onChange={event => set('name', event.target.value)} placeholder="e.g. Subscriptions" /></label><label className="field"><span>Type</span><select value={form.type} onChange={event => set('type', event.target.value)}><option value="expense">Expense</option><option value="income">Income</option></select></label><label className="field"><span>Icon</span><select value={form.icon} onChange={event => set('icon', event.target.value)}>{iconNames.map(name => <option value={name} key={name}>{name}</option>)}</select></label><label className="field"><span>Color</span><div className="color-input"><input type="color" value={form.color} onChange={event => set('color', event.target.value)} /><input value={form.color} onChange={event => set('color', event.target.value)} /></div></label><div className="form-actions"><Button type="button" variant="ghost" onClick={() => { setEditing(null); setForm({ name: '', type: 'expense', color: '#5146e5', icon: 'Tag' }) }}>Clear</Button><Button type="submit" icon="Check">{editing ? 'Save changes' : 'Add category'}</Button></div></form></SectionCard><div className="category-groups"><SectionCard title="Expense categories" subtitle={`${categories.filter(item => item.type === 'expense').length} categories`}><CategoryList items={categories.filter(item => item.type === 'expense')} transactions={transactions} onEdit={startEdit} onDelete={requestDelete} /></SectionCard><SectionCard title="Income categories" subtitle={`${categories.filter(item => item.type === 'income').length} categories`}><CategoryList items={categories.filter(item => item.type === 'income')} transactions={transactions} onEdit={startEdit} onDelete={requestDelete} /></SectionCard></div></div><Modal open={Boolean(deleting)} title="Delete category?" description="Only unused custom categories can be removed." onClose={() => setDeleting(null)}><div className="confirm-body"><div className="confirm-icon danger"><Icon name="Trash2" /></div><p>Delete <strong>{deleting?.name}</strong>? Transactions must be reassigned before a category can be removed.</p></div><div className="modal-actions"><Button variant="ghost" onClick={() => setDeleting(null)}>Cancel</Button><Button variant="danger" onClick={confirmDelete} icon="Trash2">Delete category</Button></div></Modal></>
}
function CategoryList({ items, transactions, onEdit, onDelete }) { return <div className="category-list">{items.map(category => { const count = transactions.filter(item => item.categoryId === category.id).length; return <div className="category-row" key={category.id}><span className="category-icon" style={{ background: `${category.color}18`, color: category.color }}><Icon name={category.icon} /></span><div><strong>{category.name}</strong><small>{count} transaction{count === 1 ? '' : 's'} {category.custom ? '· Custom' : '· Default'}</small></div><span className="category-swatch" style={{ background: category.color }} /><div className="row-actions"><IconButton label="Edit category" icon="Pencil" onClick={() => onEdit(category)} />{category.custom && <IconButton label="Delete category" icon="Trash2" variant="danger-icon" onClick={() => onDelete(category)} />}</div></div> })}</div> }

function SettingsPage() {
  const { transactions, budgets, categories, preferences, settings, setPreference, setSetting, loadDemo, clearSample, reset, importData } = useExpense()
  const [resetStep, setResetStep] = useState(0)
  const [resetText, setResetText] = useState('')
  const [importing, setImporting] = useState(false)
  const confirmReset = () => { if (resetText !== 'RESET') return toast.error('Type RESET to confirm.'); reset(); setResetStep(0); setResetText(''); toast.success('SpendWise was reset to an empty state') }
  const handleImport = event => { const file = event.target.files?.[0]; if (!file) return; setImporting(true); const reader = new FileReader(); reader.onload = () => { try { importData(JSON.parse(reader.result)); toast.success('Backup imported successfully') } catch (error) { toast.error(error.message || 'Import failed. Your current data is unchanged.') } finally { setImporting(false); event.target.value = '' } }; reader.readAsText(file) }
  return <><PageHeader title="Settings" description="Shape SpendWise around the way you think about money." /><div className="settings-grid"><SectionCard title="Preferences" subtitle="These choices are saved on this device"><div className="settings-list"><SettingRow icon="Moon" title="Theme" description="Choose the look that feels right." control={<select value={preferences.theme} onChange={event => setPreference('theme', event.target.value)}><option value="light">Light</option><option value="dark">Dark</option></select>} /><SettingRow icon="BadgeIndianRupee" title="Currency" description="Used across every card, chart, and export." control={<select value={preferences.currency} onChange={event => setPreference('currency', event.target.value)}><option value="INR">INR — Indian Rupee</option><option value="USD">USD — US Dollar</option><option value="EUR">EUR — Euro</option><option value="GBP">GBP — Pound Sterling</option></select>} /><SettingRow icon="CalendarDays" title="Date format" description="How dates appear across the app." control={<select value={preferences.dateFormat} onChange={event => setPreference('dateFormat', event.target.value)}><option value="dd MMM yyyy">24 Jan 2026</option><option value="MMM dd, yyyy">Jan 24, 2026</option><option value="dd/MM/yyyy">24/01/2026</option></select>} /><SettingRow icon="CalendarRange" title="Week starts on" description="Used for weekly chart groupings." control={<select value={preferences.weekStartsOn} onChange={event => setPreference('weekStartsOn', Number(event.target.value))}><option value="1">Monday</option><option value="0">Sunday</option></select>} /><SettingRow icon="ChartNoAxesCombined" title="Dashboard range" description="Months shown in the income vs expense chart." control={<select value={preferences.dashboardRange} onChange={event => setPreference('dashboardRange', Number(event.target.value))}><option value="6">Last 6 months</option><option value="12">Last 12 months</option></select>} /></div></SectionCard><SectionCard title="Data management" subtitle="Your data stays in this browser"><div className="data-summary"><div><span>Transactions</span><strong>{transactions.length}</strong></div><div><span>Budgets</span><strong>{budgets.length}</strong></div><div><span>Categories</span><strong>{categories.length}</strong></div></div><div className="settings-actions"><div className="settings-action"><span className="setting-icon green"><Icon name="Download" /></span><div><strong>Export transactions</strong><small>Download a CSV of all your activity.</small></div><Button variant="secondary" onClick={() => { exportTransactionsCsv(transactions, categories, preferences.currency); toast.success('CSV export ready') }}>Export CSV</Button></div><div className="settings-action"><span className="setting-icon indigo"><Icon name="FileJson" /></span><div><strong>Export application data</strong><small>Keep a complete JSON backup of SpendWise.</small></div><Button variant="secondary" onClick={() => { exportBackupJson({ transactions, budgets, categories, preferences, settings }); toast.success('JSON backup ready') }}>Export JSON</Button></div><div className="settings-action"><span className="setting-icon violet"><Icon name="Upload" /></span><div><strong>Import application data</strong><small>{importing ? 'Reading backup…' : 'Restore a validated SpendWise JSON backup.'}</small></div><label className="button button-secondary upload-button">Choose JSON<input type="file" accept="application/json,.json" onChange={handleImport} hidden /></label></div></div></SectionCard><SectionCard title="Sample data" subtitle="A safe way to explore or start over"><div className="sample-status"><span className={`status-dot ${preferences.demoData ? 'warning' : 'normal'}`} /><div><strong>{preferences.demoData ? 'Sample data is active' : 'You are using your own data'}</strong><p>{preferences.demoData ? 'This workspace started with realistic sample activity.' : 'Demo data will never overwrite your existing records.'}</p></div></div><div className="settings-buttons"><Button variant="secondary" icon="RefreshCw" onClick={() => { if (window.confirm('Replace current transactions and budgets with sample data?')) { loadDemo(); toast.success('Sample data loaded') } }}>Load sample data</Button>{preferences.demoData && <Button variant="ghost" icon="Eraser" onClick={() => { if (window.confirm('Clear sample transactions and budgets?')) { clearSample(); toast.success('Sample data cleared') } }}>Clear sample data</Button>}</div></SectionCard><SectionCard title="Reset SpendWise" subtitle="Delete all SpendWise data while leaving unrelated browser storage untouched" className="danger-section"><div className="reset-box"><div><span className="setting-icon coral"><Icon name="TriangleAlert" /></span><div><strong>Reset application data</strong><p>This clears transactions, budgets, custom categories, preferences, and settings. This cannot be undone.</p></div></div><Button variant="danger" onClick={() => setResetStep(1)} icon="Trash2">Reset application</Button></div></SectionCard></div><Modal open={resetStep === 1} title="Review reset" description="Please read this before continuing." onClose={() => setResetStep(0)}><div className="reset-review"><Icon name="TriangleAlert" size={30} /><p>This will delete all SpendWise transactions, budgets, categories, and preferences from this browser. Other websites’ data will not be touched.</p><strong>There is no undo.</strong></div><div className="modal-actions"><Button variant="ghost" onClick={() => setResetStep(0)}>Keep my data</Button><Button variant="danger" onClick={() => setResetStep(2)}>Continue to final confirmation</Button></div></Modal><Modal open={resetStep === 2} title="Final confirmation" description="Type RESET to permanently clear SpendWise data." onClose={() => setResetStep(0)}><label className="field"><span>Confirmation</span><input autoFocus value={resetText} onChange={event => setResetText(event.target.value)} placeholder="RESET" /></label><div className="modal-actions"><Button variant="ghost" onClick={() => setResetStep(0)}>Cancel</Button><Button variant="danger" disabled={resetText !== 'RESET'} onClick={confirmReset} icon="Trash2">Permanently reset</Button></div></Modal></>
}
function SettingRow({ icon, title, description, control }) { return <div className="setting-row"><span className="setting-icon"><Icon name={icon} /></span><div><strong>{title}</strong><small>{description}</small></div>{control}</div> }
function NotFound() { const navigate = useNavigate(); return <EmptyState icon="MapPinOff" title="Page not found" description="That view does not exist in SpendWise." action={<Button onClick={() => navigate('/')}>Back to dashboard</Button>} /> }

export default App
